272|xmlSAX2ExternalSubset(void *ctx, const xmlChar *name,
273|	       const xmlChar *ExternalID, const xmlChar *SystemID)
274|{
275|    xmlParserCtxtPtr ctxt = (xmlParserCtxtPtr) ctx;
276|    if (ctx == NULL) return;
277|    if ((SystemID != NULL) &&
278|        ((ctxt->options & XML_PARSE_NO_XXE) == 0) &&
279|        (((ctxt->validate) || (ctxt->loadsubset)) &&
280|	 (ctxt->wellFormed && ctxt->myDoc))) {
281|	/*
282|	 * Try to fetch and parse the external subset.
283|	 */
284|	xmlParserInputPtr oldinput;
285|	int oldinputNr;
286|	int oldinputMax;
287|	xmlParserInputPtr *oldinputTab;
288|	xmlParserInputPtr input = NULL;
289|	const xmlChar *oldencoding;
290|        unsigned long consumed;
291|        size_t buffered;
292|
293|	/*
294|	 * Ask the Entity resolver to load the damn thing
295|	 */
296|	if ((ctxt->sax != NULL) && (ctxt->sax->resolveEntity != NULL))
297|	    input = ctxt->sax->resolveEntity(ctxt->userData, ExternalID,
298|	                                        SystemID);
299|	if (input == NULL) {
300|	    return;
301|	}
302|
303|	if (xmlNewDtd(ctxt->myDoc, name, ExternalID, SystemID) == NULL) {
304|            xmlSAX2ErrMemory(ctxt);
305|            xmlFreeInputStream(input);
306|            return;
307|        }
308|
309|	/*
310|	 * make sure we won't destroy the main document context
311|	 */
312|	oldinput = ctxt->input;
313|	oldinputNr = ctxt->inputNr;
314|	oldinputMax = ctxt->inputMax;
315|	oldinputTab = ctxt->inputTab;
316|	oldencoding = ctxt->encoding;
317|	ctxt->encoding = NULL;
318|
319|	ctxt->inputTab = (xmlParserInputPtr *)
320|	                 xmlMalloc(5 * sizeof(xmlParserInputPtr));
321|	if (ctxt->inputTab == NULL) {
322|	    xmlSAX2ErrMemory(ctxt);
323|            xmlFreeInputStream(input);
324|	    ctxt->input = oldinput;
325|	    ctxt->inputNr = oldinputNr;
326|	    ctxt->inputMax = oldinputMax;
327|	    ctxt->inputTab = oldinputTab;
328|	    ctxt->encoding = oldencoding;
329|	    return;
330|	}
331|	ctxt->inputNr = 0;
332|	ctxt->inputMax = 5;
333|	ctxt->input = NULL;
334|	xmlPushInput(ctxt, input);
335|
336|	if (input->filename == NULL)
337|	    input->filename = (char *) xmlCanonicPath(SystemID);
338|	input->line = 1;
339|	input->col = 1;
340|	input->base = ctxt->input->cur;
341|	input->cur = ctxt->input->cur;
342|	input->free = NULL;
343|
344|	/*
345|	 * let's parse that entity knowing it's an external subset.
346|	 */
347|	xmlParseExternalSubset(ctxt, ExternalID, SystemID);
348|
349|        /*
350|	 * Free up the external entities
351|	 */
352|
353|	while (ctxt->inputNr > 1)
354|	    xmlPopInput(ctxt);
355|
356|        consumed = ctxt->input->consumed;
357|        buffered = ctxt->input->cur - ctxt->input->base;
358|        if (buffered > ULONG_MAX - consumed)
359|            consumed = ULONG_MAX;
360|        else
361|            consumed += buffered;
362|        if (consumed > ULONG_MAX - ctxt->sizeentities)
363|            ctxt->sizeentities = ULONG_MAX;
364|        else
365|            ctxt->sizeentities += consumed;
366|
367|	xmlFreeInputStream(ctxt->input);
368|        xmlFree(ctxt->inputTab);
369|
370|	/*
371|	 * Restore the parsing context of the main entity
372|	 */
373|	ctxt->input = oldinput;
374|	ctxt->inputNr = oldinputNr;
375|	ctxt->inputMax = oldinputMax;
376|	ctxt->inputTab = oldinputTab;
377|	if ((ctxt->encoding != NULL) &&
378|	    ((ctxt->dict == NULL) ||
379|	     (!xmlDictOwns(ctxt->dict, ctxt->encoding))))
380|	    xmlFree((xmlChar *) ctxt->encoding);
381|	ctxt->encoding = oldencoding;
382|	/* ctxt->wellFormed = oldwellFormed; */
383|    }
