490|/**
491| * xmlSAX2EntityDecl:
492| * @ctx: the user data (XML parser context)
493| * @name:  the entity name
494| * @type:  the entity type
495| * @publicId: The public ID of the entity
496| * @systemId: The system ID of the entity
497| * @content: the entity value (without processing).
498| *
499| * An entity definition has been parsed
500| */
501|void
502|xmlSAX2EntityDecl(void *ctx, const xmlChar *name, int type,
503|          const xmlChar *publicId, const xmlChar *systemId, xmlChar *content)
504|{
505|    xmlEntityPtr ent;
506|    xmlParserCtxtPtr ctxt = (xmlParserCtxtPtr) ctx;
507|    int extSubset;
508|    int res;
509|
510|    if ((ctxt == NULL) || (ctxt->myDoc == NULL))
511|        return;
512|
513|    extSubset = ctxt->inSubset == 2;
514|    res = xmlAddEntity(ctxt->myDoc, extSubset, name, type, publicId, systemId,
515|                       content, &ent);
516|    switch (res) {
517|        case XML_ERR_OK:
518|            break;
519|        case XML_ERR_NO_MEMORY:
520|            xmlSAX2ErrMemory(ctxt);
521|            return;
522|        case XML_WAR_ENTITY_REDEFINED:
523|            if (ctxt->pedantic) {
524|                if (extSubset)
525|                    xmlWarnMsg(ctxt, res, "Entity(%s) already defined in the"
526|                               " external subset\n", name);
527|                else
528|                    xmlWarnMsg(ctxt, res, "Entity(%s) already defined in the"
529|                               " internal subset\n", name);
530|            }
531|            return;
532|        case XML_ERR_REDECL_PREDEF_ENTITY:
533|            /*
534|             * Technically an error but it's a common mistake to get double
535|             * escaping according to "4.6 Predefined Entities" wrong.
536|             */
537|            xmlWarnMsg(ctxt, res, "Invalid redeclaration of predefined"
538|                       " entity '%s'", name);
539|            return;
540|        default:
541|            xmlFatalErrMsg(ctxt, XML_ERR_INTERNAL_ERROR,
542|                           "Unexpected error code from xmlAddEntity\n",
543|                           NULL, NULL);
544|            return;
545|    }
546|
547|    if ((ent->URI == NULL) && (systemId != NULL)) {
548|        xmlChar *URI;
549|        const char *base = NULL;
550|
551|        if (ctxt->input != NULL)
552|            base = ctxt->input->filename;
553|
554|        if (base != NULL) {
555|            if (xmlBuildURISafe(systemId, (const xmlChar *) base, &URI) < 0)
556|                xmlSAX2ErrMemory(ctxt);
557|            else
558|                ent->URI = URI;
559|        }
560|    }
