563|/**
564| * xmlSAX2AttributeDecl:
565| * @ctx: the user data (XML parser context)
566| * @elem:  the name of the element
567| * @fullname:  the attribute name
568| * @type:  the attribute type
569| * @def:  the type of default value
570| * @defaultValue: the attribute default value
571| * @tree:  the tree of enumerated value set
572| *
573| * An attribute definition has been parsed
574| */
575|void
576|xmlSAX2AttributeDecl(void *ctx, const xmlChar *elem, const xmlChar *fullname,
577|              int type, int def, const xmlChar *defaultValue,
578|	      xmlEnumerationPtr tree)
579|{
580|    xmlParserCtxtPtr ctxt = (xmlParserCtxtPtr) ctx;
581|    xmlAttributePtr attr;
582|    xmlChar *name = NULL, *prefix = NULL;
583|
584|    /* Avoid unused variable warning if features are disabled. */
585|    (void) attr;
586|
587|    if ((ctxt == NULL) || (ctxt->myDoc == NULL))
588|        return;
589|
590|    if ((xmlStrEqual(fullname, BAD_CAST "xml:id")) &&
591|        (type != XML_ATTRIBUTE_ID)) {
592|	/*
593|	 * Raise the error but keep the validity flag
594|	 */
595|	int tmp = ctxt->valid;
596|	xmlErrValid(ctxt, XML_DTD_XMLID_TYPE,
597|	      "xml:id : attribute type should be ID\n", NULL, NULL);
598|	ctxt->valid = tmp;
599|    }
600|    /* TODO: optimize name/prefix allocation */
601|    name = xmlSplitQName(ctxt, fullname, &prefix);
602|    if (name == NULL)
603|        xmlSAX2ErrMemory(ctxt);
604|    ctxt->vctxt.valid = 1;
605|    if (ctxt->inSubset == 1)
606|	attr = xmlAddAttributeDecl(&ctxt->vctxt, ctxt->myDoc->intSubset, elem,
607|	       name, prefix, (xmlAttributeType) type,
608|	       (xmlAttributeDefault) def, defaultValue, tree);
609|    else if (ctxt->inSubset == 2)
610|	attr = xmlAddAttributeDecl(&ctxt->vctxt, ctxt->myDoc->extSubset, elem,
611|	   name, prefix, (xmlAttributeType) type,
612|	   (xmlAttributeDefault) def, defaultValue, tree);
613|    else {
614|        xmlFatalErrMsg(ctxt, XML_ERR_INTERNAL_ERROR,
615|	     "SAX.xmlSAX2AttributeDecl(%s) called while not in subset\n",
616|	               name, NULL);
617|	xmlFree(name);
618|	xmlFree(prefix);
619|	xmlFreeEnumeration(tree);
620|	return;
621|    }
622|#ifdef LIBXML_VALID_ENABLED
623|    if (ctxt->vctxt.valid == 0)
624|	ctxt->valid = 0;
625|    if ((attr != NULL) && (ctxt->validate) && (ctxt->wellFormed) &&
626|        (ctxt->myDoc->intSubset != NULL))
627|	ctxt->valid &= xmlValidateAttributeDecl(&ctxt->vctxt, ctxt->myDoc,
628|	                                        attr);
629|#endif /* LIBXML_VALID_ENABLED */
630|    if (prefix != NULL)
631|	xmlFree(prefix);
632|    if (name != NULL)
633|	xmlFree(name);
