241| * Free a property and all its siblings, all the children are freed too.
242| */
243|static void
244|xmlTextReaderFreePropList(xmlTextReaderPtr reader, xmlAttrPtr cur) {
245|    xmlAttrPtr next;
246|
247|    while (cur != NULL) {
248|        next = cur->next;
249|        xmlTextReaderFreeProp(reader, cur);
250|	cur = next;
251|    }
