1808|/************************************************************************
1809| *									*
1810| *			Operating on a preparsed tree			*
1811| *									*
1812| ************************************************************************/
1813|static int
1814|xmlTextReaderNextTree(xmlTextReaderPtr reader)
1815|{
1816|    if (reader == NULL)
1817|        return(-1);
1818|
1819|    if (reader->state == XML_TEXTREADER_END)
1820|        return(0);
1821|
1822|    if (reader->node == NULL) {
1823|        if (reader->doc->children == NULL) {
1824|            reader->state = XML_TEXTREADER_END;
1825|            return(0);
1826|        }
1827|
1828|        reader->node = reader->doc->children;
1829|        reader->state = XML_TEXTREADER_START;
1830|        return(1);
1831|    }
1832|
1833|    if (reader->state != XML_TEXTREADER_BACKTRACK) {
1834|	/* Here removed traversal to child, because we want to skip the subtree,
1835|	replace with traversal to sibling to skip subtree */
1836|        if (reader->node->next != 0) {
1837|	    /* Move to sibling if present,skipping sub-tree */
1838|            reader->node = reader->node->next;
1839|            reader->state = XML_TEXTREADER_START;
1840|            return(1);
1841|        }
1842|
1843|	/* if reader->node->next is NULL mean no subtree for current node,
1844|	so need to move to sibling of parent node if present */
1845|	reader->state = XML_TEXTREADER_BACKTRACK;
1846|	/* This will move to parent if present */
1847|	xmlTextReaderRead(reader);
1848|    }
1849|
1850|    if (reader->node->next != 0) {
1851|        reader->node = reader->node->next;
1852|        reader->state = XML_TEXTREADER_START;
1853|        return(1);
1854|    }
1855|
1856|    if (reader->node->parent != 0) {
1857|        if (reader->node->parent->type == XML_DOCUMENT_NODE) {
1858|            reader->state = XML_TEXTREADER_END;
1859|            return(0);
1860|        }
1861|
1862|        reader->node = reader->node->parent;
1863|        reader->depth--;
1864|        reader->state = XML_TEXTREADER_BACKTRACK;
1865|	/* Repeat process to move to sibling of parent node if present */
1866|        xmlTextReaderNextTree(reader);
1867|    }
1868|
1869|    reader->state = XML_TEXTREADER_END;
1870|
1871|    return(1);
